const template_009 =
  '/** Query-client surface required by the generated optimistic list mutation. */\nexport interface OptimisticListQueryClient {\n  getQueryData<TData>(queryKey: readonly unknown[]): TData | undefined;\n  setQueryData<TData>(queryKey: readonly unknown[], data: TData): void;\n}\n\n/** Snapshot returned by `onMutate` and consumed by `onError`. */\nexport interface OptimisticListMutationContext<TData> {\n  readonly previous?: TData;\n}\n\nexport interface OptimisticListMutationOptions<TData, TVariables> {\n  readonly queryClient: OptimisticListQueryClient;\n  readonly queryKey: readonly unknown[];\n  readonly update: (previous: TData, variables: TVariables) => TData;\n  readonly onOptimisticUpdate?: (variables: TVariables) => void;\n  readonly onRollback?: (variables: TVariables) => void;\n}\n\n/**\n * Build executable mutation callbacks that save the cache before changing it\n * and restore that exact snapshot when the server rejects the mutation.\n */\nexport function createOptimisticListMutationCallbacks<TData, TVariables>(\n  options: OptimisticListMutationOptions<TData, TVariables>,\n) {\n  return {\n    onMutate: (variables: TVariables): OptimisticListMutationContext<TData> => {\n      const previous = options.queryClient.getQueryData<TData>(options.queryKey);\n      if (previous !== undefined) {\n        options.queryClient.setQueryData(\n          options.queryKey,\n          options.update(previous, variables),\n        );\n      }\n      options.onOptimisticUpdate?.(variables);\n      return { previous };\n    },\n    onError: (\n      _error: unknown,\n      variables: TVariables,\n      context?: OptimisticListMutationContext<TData>,\n    ): void => {\n      if (context?.previous !== undefined) {\n        options.queryClient.setQueryData(options.queryKey, context.previous);\n      }\n      options.onRollback?.(variables);\n    },\n  };\n}\n';
