  '# NetScript Environment Configuration Template\n# Copy this to .env and fill in the values\n# Supports: PostgreSQL, MySQL, MSSQL for databases\n# Supports: Garnet, Redis, Deno KV for cache\n\n# ============================================================================\n# DATABASE CONFIGURATION (Required)\n# ============================================================================\n# Choose one: postgres, mysql, mssql\n\nDATABASE_PROVIDER=mysql\nDATABASE_MODE=external\n\n# ============================================================================\n# PostgreSQL Configuration (if DATABASE_PROVIDER=postgres)\n# ============================================================================\n\n# POSTGRES_HOST=localhost\n# POSTGRES_PORT=5432\n# POSTGRES_DATABASE=postgres\n# POSTGRES_USER=postgres\n# POSTGRES_PASSWORD=YOUR_PASSWORD_HERE\n# POSTGRES_URI=postgresql://postgres:YOUR_PASSWORD_HERE@localhost:5432/postgres\n\n# ============================================================================\n# MySQL Configuration (if DATABASE_PROVIDER=mysql)\n# ============================================================================\n\nMYSQL_HOST=localhost\nMYSQL_PORT=3306\nMYSQL_DATABASE=netscript\nMYSQL_USER=root\nMYSQL_PASSWORD=YOUR_PASSWORD_HERE\nMYSQL_URI=mysql://root:YOUR_PASSWORD_HERE@localhost:3306/netscript\n\n# Legacy MYSQLDB_* format (backward compatibility)\nMYSQLDB_HOST=localhost\nMYSQLDB_PORT=3306\nMYSQLDB_DATABASENAME=netscript\nMYSQLDB_USER=root\nMYSQLDB_PASSWORD=YOUR_PASSWORD_HERE\nMYSQLDB_URI=mysql://root:YOUR_PASSWORD_HERE@localhost:3306/netscript\n\n# ============================================================================\n# Multi-Database Configuration (Optional — for multi-host MySQL setups)\n# ============================================================================\n# Use DATABASE_{DBNAME}_URL for per-database connection strings when databases\n# live on different hosts. The primary database URL is also set this way.\n#\n# DATABASE_NETSCRIPT_URL=mysql://root:YOUR_PASSWORD_HERE@db-host-1:3306/netscript\n# DATABASE_MDB_URL=mysql://root:YOUR_PASSWORD_HERE@db-host-2:3306/mdb\n# DATABASE_PROSCO_URL=mysql://root:YOUR_PASSWORD_HERE@db-host-2:3306/prosco\n#\n# Aspire connection strings (auto-injected when running via Aspire):\n# ConnectionStrings__mysql=Server=db-host-1;Port=3306;Database=netscript;User=root;Password=YOUR_PASSWORD_HERE\n# ConnectionStrings__mysql-mdb=Server=db-host-2;Port=3306;Database=mdb;User=root;Password=YOUR_PASSWORD_HERE\n# ConnectionStrings__mysql-prosco=Server=db-host-2;Port=3306;Database=prosco;User=root;Password=YOUR_PASSWORD_HERE\n\n# ============================================================================\n# MSSQL Configuration (if DATABASE_PROVIDER=mssql)\n# ============================================================================\n\n# MSSQL_HOST=localhost\n# MSSQL_PORT=1433\n# MSSQL_DATABASE=master\n# MSSQL_USER=sa\n# MSSQL_PASSWORD=YOUR_PASSWORD_HERE\n# MSSQL_URI=sqlserver://sa:YOUR_PASSWORD_HERE@localhost:1433/master\n\n# ============================================================================\n# CACHE CONFIGURATION (Required)\n# ============================================================================\n# Choose one: garnet, redis, denokv\n\nCACHE_PROVIDER=garnet\nCACHE_MODE=external\n\n# ============================================================================\n# Garnet/Redis Configuration (if CACHE_PROVIDER=garnet or redis)\n# ============================================================================\n\nGARNET_HOST=127.0.0.1\nGARNET_PORT=6379\nGARNET_SSL=false\nGARNET_DATABASE=0\nGARNET_URI=redis://127.0.0.1:6379\n\n# ============================================================================\n# Deno KV Configuration (if CACHE_PROVIDER=denokv)\n# ============================================================================\n\n# DENO_KV_PATH=data/kv\n\n# ============================================================================\n# OPENTELEMETRY (Optional)\n# ============================================================================\n\nOTEL_EXPORTER_OTLP_ENDPOINT=http://localhost:4318\nOTEL_EXPORTER_OTLP_PROTOCOL=http/protobuf\nOTEL_DENO=true\n\n# ============================================================================\n# FILE-WATCH TRIGGER PATHS (Optional)\n# ============================================================================\n# Semicolon-separated UNC or local paths watched by file-trigger processors.\n# Leave empty (or remove) to disable the corresponding trigger gracefully.\n#\n# Format: //SERVER/Share$/path/to/dir;/local/path/to/dir\n#   UNC paths require the service account to have network share access.\n#   Set SERVY_SERVICE_ACCOUNT to a domain user with read/write on the share.\n#\n# TRIGGER_CSV_IMPORT_PATHS=//SERVER/Share$/data_in/prod;//SERVER/Share$/data_in/test\n# TRIGGER_PRODUCT_IMPORT_PATHS=//SERVER/Share$/documents/products\n# TRIGGER_EXPORT_OUTGOING_PATH=//SERVER/Share$/exports/outgoing\n\n# ============================================================================\n# RUNTIME CONFIG HOT-RELOAD (Optional)\n# ============================================================================\n# Root directory for job/saga/trigger/feature runtime overrides.\n# Defaults to {installDir}/runtime when not set.\n# Override only if you store runtime configs in a custom location.\n#\n# NETSCRIPT_RUNTIME_CONFIG_DIR=C:\\\\NetScript\\\\my-app\\\\runtime\n\n# ============================================================================\n# SERVY SERVICE ACCOUNT (Optional — Windows deployment only)\n# ============================================================================\n# By default, services run as LOCAL SYSTEM which has no network identity.\n# Set these to run services under a specific user account — required when\n# services need to access UNC network shares (e.g. \\\\\\\\SERVER\\\\Share$).\n#\n# Supported formats:\n#   .\\\\username           — local account\n#   DOMAIN\\\\username      — domain account\n#   DOMAIN\\\\gMSA$         — group Managed Service Account (no password needed)\n#\n# SERVY_SERVICE_ACCOUNT=DOMAIN\\\\username\n# SERVY_SERVICE_PASSWORD=YOUR_PASSWORD_HERE\n\n# ============================================================================\n# CUSTOM SETTINGS\n# ============================================================================\n\n# Add any additional environment variables here\n';
